questionvariables.text:
/*lighthouse from ship between 95 and 120 */
bearhh:rand(25)+95;

/*port from lighthouse between 190 and 240 so that it is between south and west on diagram and leaves at angle between 35 and 110 for angle they need to find */
bearpp:rand_with_prohib(190,240,[180+bearhh-90,180+bearhh-60,180+bearhh-45]);

/*Ship is between 80 and 99 km away and the port is between 50 and 79km away */
ss:rand(19)+80;
pp:rand(29)+50;

/*co-interior angles*/
aa:180-bearhh;
/*angle in triangle at lighthouse */
tt:360-bearpp-aa;
/*Teacher answer using cosine rule */
squared:ss^2+pp^2-2*ss*pp*cos(tt*pi/180);
exactside:sqrt(squared);
tans1:significantfigures(exactside,3);

feedbackvariables.text:
/* Mistake Node 3: calculator in radians */
mistake3:sqrt(ss^2+pp^2-2*ss*pp*cos(tt));

/* Mistake node 4 - Using pythag with x as hypotenuse */
mistake4:sqrt(ss^2+pp^2);

/* Mistake node 5 - Using pythag with ss as hypotenuse */
mistake5:if ss^2-pp^2>0 then sqrt(ss^2-pp^2) else 0;

/* Mistake node 6 - Using pythag with pp as hypotenuse */
mistake6:if pp^2-ss^2>0 then sqrt(pp^2-ss^2) else 0;

/* Mistake node 7 - Thinking the co-interior angle at L is the same as the bearing from of L from S */
mistake7:if ss^2+pp^2-2*ss*pp*cos((360-bearhh-bearpp)*pi/180)>0 then sqrt(ss^2+pp^2-2*ss*pp*cos((360-bearhh-bearpp)*pi/180)) else 0;

/* Mistake node 8 - cos rule without squares */
mistake8:ss+pp-2*ss*pp*cos(tt*pi/180);

/* Mistake node 9 - forgetting the square root */
mistake9:ss^2+pp^2-2*ss*pp*cos(tt*pi/180);

/* Nodes 10 and 11 test for incorrect number of significant figures */
